<?php $latestControl=$controls[0] ?? null; $tasks=$ortho['tasks'] ?? []; $openTasks=array_filter($tasks,static fn($t)=>($t['status'] ?? 'pending')==='pending'); $donePhases=count(array_filter($phases,static fn($p)=>($p['status'] ?? '')==='completed')); $relevantPhases=count(array_filter($phases,static fn($p)=>($p['status'] ?? '')!=='not_applicable')); ?>
<div class="orth-summary-grid"><section class="panel"><div class="orth-section-heading"><div><span class="orth-kicker">ESTADO ACTUAL</span><h3>El tratamiento, de un vistazo</h3></div><?= icon('heart',21) ?></div><dl class="orth-facts"><div><dt>Tratamiento</dt><dd><?= e($orthoLabel($case['type_key'] ?? '',$typeNames)) ?></dd></div><div><dt>Aparatología</dt><dd><?= e($case['appliance'] ?: 'Sin registrar') ?></dd></div><div><dt>Inicio</dt><dd><?= $orthoDate($case['start_date'] ?? null) ?></dd></div><div><dt>Duración estimada</dt><dd><?= !empty($case['estimated_months'])?(int)$case['estimated_months'].' meses':'Sin registrar' ?></dd></div><div><dt>Último control</dt><dd><?= $latestControl ? local_date($latestControl['occurred_at'] ?? null,'d/m/Y'):'Sin controles' ?></dd></div><div><dt>Frecuencia</dt><dd><?= !empty($case['control_interval_days'])?'Cada '.(int)$case['control_interval_days'].' días':'Sin registrar' ?></dd></div></dl><?php if($relevantPhases): ?><div class="orth-progress-block"><div><strong>Fases documentadas</strong><span><?= $donePhases ?> de <?= $relevantPhases ?></span></div><div class="orth-progress-track"><i data-percent="<?= (int)round($donePhases/$relevantPhases*100) ?>"></i></div><small>El avance se basa en fases registradas por el profesional.</small></div><?php endif; ?></section>
<section class="panel"><div class="orth-section-heading"><div><span class="orth-kicker">PRÓXIMAS ACCIONES</span><h3>Pendientes de seguimiento <span class="orth-count"><?= count($openTasks) ?></span></h3></div><a class="orth-link" href="<?= e($caseLink('appointments')) ?>">Gestionar</a></div><?php if(!$openTasks): $orthoEmpty('Sin tareas pendientes','Las tareas y alertas de seguimiento aparecerán aquí.','check'); else: ?><div class="orth-task-list"><?php foreach(array_slice($openTasks,0,5) as $task): ?><div class="orth-task"><span class="orth-task-dot <?= e($task['priority'] ?? 'normal') ?>"></span><div><strong><?= e($task['title']) ?></strong><small><?= $orthoDate($task['due_date'] ?? null) ?> · <?= e(label($task['priority'] ?? 'normal')) ?></small></div><?php if($canAssist): ?><form method="post"><?php $orthoFields('task_status',$case); ?><input type="hidden" name="task_id" value="<?= (int)$task['id'] ?>"><input type="hidden" name="status" value="completed"><button class="orth-icon-link" aria-label="Completar tarea <?= e($task['title']) ?>"><?= icon('check',18) ?></button></form><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?><?php if(!empty($case['next_control']) && $case['next_control']<date('Y-m-d') && !in_array($case['status'],['completed','cancelled'])): ?><div class="orth-callout warning">El control previsto para <?= $orthoDate($case['next_control']) ?> está pendiente. Revisa la evolución y la agenda antes de reprogramar.</div><?php endif; ?></section></div>
<div class="orth-summary-grid"><section class="panel"><div class="orth-section-heading"><div><span class="orth-kicker">ÚLTIMA EVALUACIÓN</span><h3>Diagnóstico y objetivos</h3></div><a class="orth-link" href="<?= e($caseLink('diagnosis')) ?>">Consultar</a></div><div class="orth-panel-body"><?php $orthoText('Diagnóstico clínico',$diagnosis['clinical_diagnosis'] ?? ''); $orthoText('Objetivos registrados',$diagnosis['objectives'] ?? $plan['objectives'] ?? ''); ?><?php if(!empty($patient['allergies']) || !empty($patient['record']['allergies'])): ?><div class="orth-callout warning"><strong>Alergias registradas</strong><p><?= e($patient['allergies'] ?? $patient['record']['allergies']) ?></p></div><?php endif; ?></div></section>
<section class="panel"><div class="orth-section-heading"><div><span class="orth-kicker">CONTINUIDAD DEL CUIDADO</span><h3>Última evolución</h3></div><a class="orth-link" href="<?= e($caseLink('controls')) ?>">Ver todas</a></div><?php if(!$latestControl): $orthoEmpty('La evolución comienza en el primer control','Cada visita conservará sus observaciones, procedimientos e indicaciones.','chart'); else: ?><div class="orth-panel-body"><div class="orth-control-meta"><strong><?= local_date($latestControl['occurred_at'] ?? null) ?></strong><span><?= e($latestControl['professional'] ?? '') ?></span></div><?php $orthoText('Observaciones',$latestControl['observations'] ?? $latestControl['notes'] ?? $latestControl['findings'] ?? ''); $orthoText('Procedimientos',$latestControl['procedures'] ?? $latestControl['procedures_done'] ?? ''); $orthoText('Recomendaciones',$latestControl['recommendations'] ?? $latestControl['instructions'] ?? ''); ?></div><?php endif; ?></section></div>
<section class="panel"><div class="orth-section-heading"><div><span class="orth-kicker">ESTADO CLÍNICO OBSERVADO</span><h3>Odontograma del paciente</h3></div><?php if(can('clinical')): ?><a class="button secondary small" href="<?= e(url('/admin/odontogram?patient_id='.$case['patient_id'])) ?>">Abrir odontograma <?= icon('arrow',15) ?></a><?php endif; ?></div><?php $odontogram=$ortho['odontogram'] ?? []; $findings=$odontogram['findings'] ?? []; $observed=[];foreach($findings as $finding){ if(is_array($finding) && isset($finding['tooth_fdi']))$observed[(int)$finding['tooth_fdi']][]=$finding; }  $dentalArches=[[18,17,16,15,14,13,12,11,21,22,23,24,25,26,27,28],[48,47,46,45,44,43,42,41,31,32,33,34,35,36,37,38]]; $primaryArches=[[55,54,53,52,51,61,62,63,64,65],[85,84,83,82,81,71,72,73,74,75]]; $registeredDentition=$odontogram['latest']['dentition_type'] ?? 'permanent'; if($registeredDentition==='pediatric')$dentalArches=$primaryArches; elseif($registeredDentition==='mixed')$dentalArches=array_merge($dentalArches,$primaryArches); ?><div class="orth-dental-map" aria-label="Mapa FDI del último odontograma"><?php foreach($dentalArches as $arch): ?><div class="orth-dental-arch"><?php foreach($arch as $fdi): $toothFindings=$observed[$fdi] ?? []; $toothTitle=implode('; ',array_map(static fn($f)=>label($f['state'] ?? '').(!empty($f['observation'])?': '.$f['observation']:''),$toothFindings)); ?><span class="orth-tooth <?= $toothFindings?'has-finding':'' ?>" tabindex="0" title="<?= e($toothTitle ?: 'Sin hallazgos registrados en esta pieza') ?>"><?= icon('tooth',24) ?><b><?= $fdi ?></b><span class="orth-tooth-info"><?= e($toothTitle ?: 'Sin hallazgos registrados') ?></span></span><?php endforeach; ?></div><?php endforeach; ?></div><p class="orth-help orth-panel-body">Numeración FDI del odontograma existente. Los hallazgos registrados describen el estado observado; los objetivos del plan se consultan por separado.<?= !$findings?' Aún no hay hallazgos disponibles en este expediente.':'' ?></p></section>
<?php if($canWrite): ?><details class="panel orth-form-panel"><summary><?= icon('settings',18) ?><span>Actualizar estado del caso</span><small>Queda registrado en el historial</small></summary><form method="post" class="form-grid orth-panel-body" data-orth-dirty data-loading><?php $orthoFields('status',$case); choose('status','Nuevo estado',$stateNames,$case['status']); area('reason','Motivo del cambio','',true); area('completion_criteria','Criterios clínicos de finalización comprobados',$case['completion_criteria'] ?? ''); field('retainer_type','Tipo de retenedor',$case['retainer_type'] ?? '','text',false,'maxlength="160"'); area('retention_instructions','Indicaciones y controles de retención',$case['retention_instructions'] ?? ''); ?><label class="orth-check full"><input type="checkbox" name="confirm_completion" value="1">Confirmo clínicamente que se cumplen los criterios de finalización, si corresponde.</label><p class="orth-help full">La duración estimada no produce un alta automática. La finalización y la retención requieren información y confirmación del profesional.</p><button class="button">Guardar cambio de estado</button></form></details><?php endif; ?>
